      737→export function createNodeSubprocessExecutor(): SubprocessExecutor {
      738→  return request => new Promise((resolve, reject) => {
      739→    const child = spawn(request.command, request.args, {
      740→      cwd: request.cwd,
      741→      stdio: ['ignore', 'pipe', 'pipe'],
      742→      signal: request.signal,
      743→      env: request.env ? { ...process.env, ...request.env } : process.env,
      744→    });
