      758→      if (request.signal?.aborted) {
      759→        resolveOnce({
      760→          exitCode: 1,
      761→          stdout,
      762→          stderr: stderr || (error instanceof Error ? error.message : String(error)),
      763→        });
      764→        return;
      765→      }
      766→      if (settled) return;
      767→      settled = true;
      768→      reject(error);
      769→    });
      770→    child.once('close', code => resolveOnce({ exitCode: code ?? 1, stdout, stderr }));
      771→  });
      772→}
