      779→  const controller = new AbortController();
      780→  let timeoutTriggered = false;
      781→  const abortFromParent = (): void => controller.abort(parent?.reason);
      782→  if (parent?.aborted) {
      783→    abortFromParent();
      784→  } else {
      785→    parent?.addEventListener('abort', abortFromParent, { once: true });
      786→  }
      787→
      788→  let timer: NodeJS.Timeout | undefined;
      789→  if (timeoutMs !== undefined && Number.isFinite(timeoutMs) && timeoutMs > 0) {
      790→    timer = setTimeout(() => {
      791→      timeoutTriggered = true;
      792→      controller.abort();
      793→    }, timeoutMs);
      794→  }
      795→
      796→  return {
      797→    signal: controller.signal,
      798→    timedOut: () => timeoutTriggered,
      799→    dispose: () => {
      800→      if (timer) clearTimeout(timer);
      801→      parent?.removeEventListener('abort', abortFromParent);
      802→    },
      803→  };
