      168→  constructor(sandboxName: string) {
      169→    super(`Docker Sandbox "${sandboxName}" was cancelled.`);
      170→    this.name = 'SandboxRunCancelledError';
      171→  }
      172→}
      173→
      174→export class SandboxRunTimeoutError extends Error {
      175→  readonly code = 'sandbox_timeout';
      176→
      177→  constructor(sandboxName: string, readonly timeoutMs: number) {
      178→    super(`Docker Sandbox "${sandboxName}" timed out after ${timeoutMs} ms.`);
      179→    this.name = 'SandboxRunTimeoutError';
