      182→
      183→/**
      184→ * Orchestre l'exécution d'un nœud Codex dans un clone Docker Sandbox privé.
      185→ *
      186→ * Le runtime crée un Agent Checkpoint attribuable et le récupère côté hôte,
      187→ * mais ne le promeut jamais. L'intégration et la Promotion appartiennent au
      188→ * coordinateur du pipeline une fois le DAG complet.
      189→ * Il transmet aussi les signaux d'arrêt à sbx, exporte les diagnostics, puis
      190→ * conserve ou nettoie la ressource sans masquer le résultat du pipeline.
      191→ *
      192→ * Voir les ADR 0001 et 0002 sous `docs/adr/`.
      193→ */
      194→export class DockerSandboxRuntime {
      195→  private networkPolicyReady?: Promise<void>;
      196→  private networkPolicyAbort?: AbortController;
      197→  private activePreflights = 0;
      198→  private readonly cleanupTimeoutMs: number;
      199→  private readonly options: DockerSandboxRuntimeOptions;
      200→
      201→  constructor(
      202→    private readonly execute: SubprocessExecutor = createNodeSubprocessExecutor(),
      203→    cleanupTimeoutMsOrOptions: number | DockerSandboxRuntimeOptions = DEFAULT_SANDBOX_CLEANUP_TIMEOUT_MS,
      204→    options: DockerSandboxRuntimeOptions = {},
      205→  ) {
      206→    this.cleanupTimeoutMs = typeof cleanupTimeoutMsOrOptions === 'number'
      207→      ? cleanupTimeoutMsOrOptions
      208→      : DEFAULT_SANDBOX_CLEANUP_TIMEOUT_MS;
      209→    this.options = typeof cleanupTimeoutMsOrOptions === 'number'
      210→      ? options
      211→      : cleanupTimeoutMsOrOptions;
      212→  }
      213→
      214→  async runCodex(input: SandboxRunInput): Promise<SandboxRunResult> {
      215→    const sandboxName = input.resumeState?.sandboxName ?? stableSandboxName(input.runId, input.nodeId, input.attempt);
      216→    const execution = createExecutionSignal(input.signal, input.timeoutMs);
      217→    const startedAt = new Date().toISOString();
      218→    let created = false;
      219→    let stdout = '';
      220→    let stderr = '';
      221→    let terminalStatus: SandboxRunTerminalStatus = 'failed';
      222→    let failure: unknown;
      223→    let durableState: SandboxRunState | undefined;
      224→
      225→    try {
      226→      await this.preflightWorkspace(
      227→        input.workspaceCwd,
      228→        input.workspaceEffects !== false,
      229→        execution.signal,
      230→        input.resumeState ? [] : [sandboxName],
      231→      );
      232→      let baseCommit: string;
      233→      if (input.resumeState) {
      234→        baseCommit = input.resumeState.baseCommit;
      235→        if (input.resumeState.resourceState === 'removed' && input.resumeState.checkpoint) {
      236→          durableState = { ...input.resumeState };
      237→        } else {
      238→          const reconciled = await this.reconcileSandbox({
      239→            workspaceCwd: input.workspaceCwd,
      240→            sandboxName: input.resumeState.sandboxName,
      241→            sandboxId: input.resumeState.sandboxId,
      242→            baseCommit: input.resumeState.baseCommit,
      243→            checkpointCommit: input.resumeState.checkpoint?.checkpoint.commit,
      244→          });
      245→          if (reconciled.status === 'diverged') throw new SandboxResumeDivergenceError(reconciled.diagnostic);
      246→          created = reconciled.status === 'reusable';
      247→          durableState = {
      248→            ...input.resumeState,
      249→            resourceState: reconciled.status === 'removed' ? 'removed' : input.resumeState.resourceState,
      250→            ...(reconciled.status === 'reusable' && reconciled.sandboxId ? { sandboxId: reconciled.sandboxId } : {}),
      251→          };
      252→        }
      253→        stdout = durableState.stdout ?? '';
      254→        stderr = durableState.stderr ?? '';
      255→      } else {
      256→        baseCommit = (await this.requireSuccess({
      257→          command: 'git',
      258→          args: ['rev-parse', 'HEAD'],
      259→          cwd: input.workspaceCwd,
      260→          stdin: 'ignore',
      261→          signal: execution.signal,
      262→        }, 'read the host base commit')).stdout.trim();
      263→        if (!baseCommit) throw new Error('Unable to read the host base commit: git returned an empty commit id.');
      264→        await this.requireSuccess({
      265→          command: 'sbx',
      266→          args: ['create', '--clone', '--name', sandboxName,
      267→            input.agent === 'vibe' ? 'docker.io/sbx/vibe-kit:latest' : 'codex', '.'],
      268→          cwd: input.workspaceCwd,
      269→          stdin: 'ignore',
      270→          signal: execution.signal,
      271→        }, 'create the Docker Sandbox');
      272→        created = true;
      273→        if (input.dependencyCheckpoints?.length) {
      274→          const composed = await new GitPromotion(this.execute).integrateAgentCheckpoints({
      275→            workspaceCwd: input.workspaceCwd,
      276→            runId: input.runId,
      277→            checkpoints: input.dependencyCheckpoints,
      278→            signal: execution.signal,
      279→          });
      280→          const remote = `sandbox-${sandboxName}`;
      281→          const dependencyRef = `refs/slopify/dependencies/${input.runId}/${input.nodeId}/${input.attempt}`;
      282→          await this.requireSuccess({
      283→            command: 'git', args: ['push', '--force', remote, `${composed.changeSet.commit}:${dependencyRef}`],
      284→            cwd: input.workspaceCwd, stdin: 'ignore', signal: execution.signal,
      285→          }, 'publish dependency checkpoints to the descendant sandbox');
      286→          await this.requireSuccess({
      287→            command: 'sbx', args: ['exec', sandboxName, 'git', 'reset', '--hard', dependencyRef],
      288→            cwd: input.workspaceCwd, stdin: 'ignore', signal: execution.signal,
      289→          }, 'prepare the descendant sandbox from dependency checkpoints');
      290→        }
      291→        const sandboxId = await this.readSandboxId(input.workspaceCwd, sandboxName, execution.signal);
      292→        durableState = {
      293→          sandboxName,
      294→          ...(sandboxId ? { sandboxId } : {}),
      295→          runId: input.runId,
      296→          nodeId: input.nodeId,
      297→          attempt: input.attempt,
      298→          baseCommit,
      299→          integrationState: 'sandbox_created',
      300→          resourceState: 'active',
      301→          ...(input.diagnosticsDirectory
      302→            ? { diagnosticsPath: path.join(input.diagnosticsDirectory, `${sandboxName}.json`) }
      303→            : {}),
      304→        };
      305→      }
      306→      await input.onStateChange?.(durableState);
      307→
      308→      if (durableState.checkpoint) {
      309→        terminalStatus = 'completed';
      310→        return {
      311→          ...durableState.checkpoint,
      312→          ...(durableState.checkpoint.checkpointStatus === 'no_changes' ? { status: 'no_changes' as const } : {}),
      313→          sandboxName,
      314→          stdout,
      315→          stderr,
      316→        };
      317→      }
      318→
      319→      const agent = input.agent ?? 'codex';
      320→      // Vibe resolves active_model through its model catalogue. Declare the
      321→      // requested API model as well to prevent a silent fallback to its default.
      322→      const vibeModels = JSON.stringify({
      323→        [input.model]: { name: input.model, alias: input.model, provider: 'mistral' },
      324→      });
      325→      const agentArgs = agent === 'vibe'
      326→        ? ['exec', '--env', `VIBE_ACTIVE_MODEL=${input.model}`, '--env', `VIBE_MODELS=${vibeModels}`,
      327→          sandboxName, 'vibe', '--prompt', input.prompt, '--auto-approve', '--trust', '--output', 'json']
      328→        : ['exec', sandboxName, 'codex', 'exec', '--dangerously-bypass-approvals-and-sandbox', '--ephemeral', '--json'];
      329→      if (agent === 'codex' && input.model) agentArgs.push('--model', input.model);
      330→      if (agent === 'codex' && input.effort) agentArgs.push('--config', `model_reasoning_effort=${JSON.stringify(input.effort)}`);
      331→      if (agent === 'codex') agentArgs.push(input.prompt);
      332→      const codex = await this.execute({
      333→        command: 'sbx',
      334→        args: agentArgs,
      335→        cwd: input.workspaceCwd,
      336→        stdin: 'ignore',
      337→        observeOutput: true,
      338→        signal: execution.signal,
      339→      });
      340→      stdout = codex.stdout;
      341→      stderr = codex.stderr;
      342→      this.assertSuccess(codex, `run ${agent === 'vibe' ? 'Mistral Vibe' : 'Codex'} non-interactively`);
      343→
      344→      const checkpoint = await new GitPromotion(this.execute).createAgentCheckpoint({
      345→        workspaceCwd: input.workspaceCwd,
      346→        sandboxName,
      347→        baseCommit,
      348→        runId: input.runId,
      349→        nodeId: input.nodeId,
      350→        attempt: input.attempt,
      351→        signal: execution.signal,
      352→      });
      353→      durableState = {
      354→        ...durableState,
      355→        integrationState: 'checkpointed',
      356→        checkpoint,
      357→        stdout,
      358→        stderr,
      359→      };
      360→      await input.onStateChange?.(durableState);
      361→      terminalStatus = 'completed';
      362→      return {
      363→        ...checkpoint,
      364→        ...(checkpoint.checkpointStatus === 'no_changes' ? { status: 'no_changes' as const } : {}),
      365→        sandboxName,
      366→        stdout,
      367→        stderr,
      368→      };
      369→    } catch (error: unknown) {
      370→      failure = normalizeRunError(error, sandboxName, input.signal, execution.timedOut(), input.timeoutMs);
      371→      terminalStatus = failure instanceof SandboxRunTimeoutError
      372→        ? 'timed_out'
      373→        : failure instanceof SandboxRunCancelledError
      374→          ? 'cancelled'
      375→          : 'failed';
      376→      throw failure;
      377→    } finally {
      378→      execution.dispose();
      379→      if (created) {
      380→        const retained = input.keepSandbox === true;
      381→        const commands = retained ? retainedSandboxCommands(sandboxName) : undefined;
      382→        const diagnostic: SandboxRunDiagnostic = {
      383→          sandboxName,
      384→          runId: input.runId,
      385→          nodeId: input.nodeId,
      386→          attempt: input.attempt,
      387→          status: terminalStatus,
      388→          startedAt,
      389→          finishedAt: new Date().toISOString(),
      390→          retained,
      391→          stdout,
      392→          stderr,
      393→          ...(failure === undefined ? {} : { error: formatUnknownError(failure) }),
      394→          ...(commands ? { commands } : {}),
      395→          cleanup: { attempted: !retained },
      396→        };
      397→        let diagnosticsPath = await writeSandboxDiagnostic(input.diagnosticsDirectory, diagnostic);
      398→
      399→        if (retained) {
      400→          try {
      401→            await input.onSandboxRetained?.({
      402→              sandboxName,
      403→              commands: commands!,
      404→              ...(diagnosticsPath ? { diagnosticsPath } : {}),
      405→            });
      406→          } catch (error: unknown) {
      407→            diagnostic.retentionNotificationError = formatUnknownError(error);
      408→            diagnosticsPath = await writeSandboxDiagnostic(input.diagnosticsDirectory, diagnostic) ?? diagnosticsPath;
      409→          }
      410→        } else {
      411→          // `rm --force` rend le nettoyage répétable après une annulation ou
      412→          // une erreur sans masquer le résultat principal du pipeline.
      413→          diagnostic.cleanup = await this.cleanupSandbox(input.workspaceCwd, sandboxName);
      414→          await writeSandboxDiagnostic(input.diagnosticsDirectory, diagnostic);
      415→        }
      416→        if (durableState) {
      417→          durableState = {
      418→            ...durableState,
      419→            resourceState: retained ? 'retained' : 'removed',
      420→            ...(diagnosticsPath ? { diagnosticsPath } : {}),
      421→          };
      422→          await input.onStateChange?.(durableState);
      423→        }
      424→      }
      425→    }
      426→  }
      427→
      428→  /**
      429→   * Compare un état durable avec la ressource réellement exposée par Docker.
      430→   * Cette opération est volontairement en lecture seule : un doute suspend la
      431→   * reprise et ne crée, ne supprime ni ne promeut jamais implicitement.
      432→   */
      433→  async reconcileSandbox(input: SandboxResumeSnapshot): Promise<SandboxReconciliationResult> {
      434→    const listed = await this.requireSuccess({
      435→      command: 'sbx',
      436→      args: ['ls', '--json'],
      437→      cwd: input.workspaceCwd,
      438→      stdin: 'ignore',
      439→    }, 'list Docker Sandboxes for pipeline resume');
      440→    const resources = parseSandboxList(listed.stdout);
      441→    const observed = resources.find(resource => resource.name === input.sandboxName);
      442→    if (!observed) {
      443→      if (input.checkpointCommit) {
      444→        return { status: 'removed', sandboxName: input.sandboxName };
      445→      }
      446→      return {
      447→        status: 'diverged',
      448→        sandboxName: input.sandboxName,
      449→        diagnostic: `Sandbox resume divergence: ${input.sandboxName} is absent from sbx ls --json.`,
      450→      };
      451→    }
      452→    if (input.sandboxId && observed.id !== input.sandboxId) {
      453→      return {
      454→        status: 'diverged',
      455→        sandboxName: input.sandboxName,
      456→        diagnostic: `Sandbox identity divergence: observed ${observed.id ?? 'no stable id'}, expected ${input.sandboxId}.`,
      457→      };
      458→    }
      459→
      460→    const head = (await this.requireSuccess({
      461→      command: 'sbx',
      462→      args: ['exec', input.sandboxName, 'git', 'rev-parse', 'HEAD'],
      463→      cwd: input.workspaceCwd,
      464→      stdin: 'ignore',
      465→    }, `read resumed Docker Sandbox ${input.sandboxName} commit`)).stdout.trim();
      466→    const expectedHead = input.checkpointCommit ?? input.baseCommit;
      467→    if (head !== expectedHead) {
      468→      return {
      469→        status: 'diverged',
      470→        sandboxName: input.sandboxName,
      471→        diagnostic: `Sandbox base divergence: expected persisted base ${input.baseCommit} with head ${expectedHead}, observed ${head || 'an empty commit'}.`,
      472→      };
      473→    }
      474→    if (input.checkpointCommit) {
      475→      const ancestry = await this.execute({
      476→        command: 'sbx',
      477→        args: ['exec', input.sandboxName, 'git', 'merge-base', '--is-ancestor', input.baseCommit, input.checkpointCommit],
      478→        cwd: input.workspaceCwd,
      479→        stdin: 'ignore',
      480→      });
      481→      if (ancestry.exitCode !== 0) {
      482→        return {
      483→          status: 'diverged',
      484→          sandboxName: input.sandboxName,
      485→          diagnostic: `Sandbox base divergence: persisted base ${input.baseCommit} is not an ancestor of checkpoint ${input.checkpointCommit}.`,
      486→        };
      487→      }
      488→    }
      489→    const worktree = await this.requireSuccess({
      490→      command: 'sbx',
      491→      args: ['exec', input.sandboxName, 'git', 'status', '--porcelain=v1'],
      492→      cwd: input.workspaceCwd,
      493→      stdin: 'ignore',
      494→    }, `inspect resumed Docker Sandbox ${input.sandboxName} worktree`);
      495→    if (worktree.stdout.trim()) {
      496→      return {
      497→        status: 'diverged',
      498→        sandboxName: input.sandboxName,
      499→        diagnostic: `Sandbox worktree divergence: ${input.sandboxName} contains uncheckpointed changes and cannot be resumed deterministically.`,
      500→      };
      501→    }
      502→    return {
      503→      status: 'reusable',
      504→      sandboxName: input.sandboxName,
      505→      ...(observed.id ? { sandboxId: observed.id } : {}),
      506→      observedCommit: head,
      507→    };
      508→  }
      509→
      510→  async preflightWorkspace(
      511→    cwd: string,
      512→    workspaceEffects = true,
      513→    signal?: AbortSignal,
      514→    plannedSandboxNames: readonly string[] = [],
      515→  ): Promise<void> {
      516→    this.activePreflights += 1;
      517→    try {
      518→      await this.requireSuccess({ command: 'git', args: ['rev-parse', '--is-inside-work-tree'], cwd, stdin: 'ignore', signal }, 'verify that the workspace is a Git repository');
      519→      if (workspaceEffects) {
      520→        // `sbx --clone` ne voit pas les changements non commités. Autoriser un
      521→        // workspace sale ferait donc calculer le Pipeline Change Set depuis une
      522→        // base différente de celle que la Promotion doit avancer atomiquement.
      523→        const status = await this.requireSuccess({
      524→          command: 'git',
      525→          args: [
      526→            'status',
      527→            '--porcelain=v1',
      528→            '--',
      529→            '.',
      530→            ':(exclude).acp/logs',
      531→            ':(exclude).acp/runs-v3',
      532→          ],
      533→          cwd,
      534→          stdin: 'ignore',
      535→          signal,
      536→        }, 'inspect the Git workspace');
      537→        if (status.stdout.trim()) {
      538→          throw new Error('Docker Sandbox requires a clean Git workspace for workspace-writing pipelines: sbx --clone cannot see uncommitted changes, so safe Promotion is impossible. Commit or remove the local changes and retry.');
      539→        }
      540→      }
      541→      const version = await this.requireSuccess({ command: 'sbx', args: ['version'], cwd, stdin: 'ignore', signal }, 'read the Docker Sandbox version');
      542→      const actual = extractVersion(`${version.stdout}\n${version.stderr}`);
      543→      if (!actual || compareVersions(actual, MINIMUM_SBX_VERSION) < 0) {
      544→        throw new Error(`Docker Sandbox sbx ${MINIMUM_SBX_VERSION} or newer is required (found ${actual ?? 'an unknown version'}). Upgrade Docker Sandboxes (sbx) and retry.`);
      545→      }
      546→      await this.requireCapability(cwd, ['create', '--help'], '--clone', signal);
      547→      await this.requireCapability(cwd, ['ls', '--help'], '--json', signal);
      548→      if (plannedSandboxNames.length > 0) {
      549→        const listed = await this.requireSuccess({
      550→          command: 'sbx', args: ['ls', '--json'], cwd, stdin: 'ignore', signal,
      551→        }, 'check planned Docker Sandbox names');
      552→        const occupiedNames = new Set(parseSandboxList(listed.stdout).map(resource => resource.name));
      553→        const collision = plannedSandboxNames.find(name => occupiedNames.has(name));
      554→        if (collision) {
      555→          throw new Error(`Docker Sandbox name collision: ${collision} already exists and cannot be reused without matching persisted state.`);
      556→        }
      557→      }
      558→      await this.requireCapability(cwd, ['policy', 'init', '--help'], 'policy init', signal, false);
      559→      await this.ensureGlobalNetworkPolicy(cwd, signal);
      560→    } finally {
      561→      this.activePreflights -= 1;
      562→      if (signal?.aborted && this.activePreflights === 0) {
      563→        this.networkPolicyAbort?.abort(signal.reason);
      564→      }
      565→    }
      566→  }
      567→
      568→  private async ensureGlobalNetworkPolicy(cwd: string, signal?: AbortSignal): Promise<void> {
      569→    if (!this.networkPolicyReady) {
      570→      const abort = new AbortController();
      571→      const initialization = this.initializeGlobalNetworkPolicy(cwd, abort.signal);
      572→      this.networkPolicyAbort = abort;
      573→      this.networkPolicyReady = initialization;
      574→      void initialization.catch(() => {
      575→        if (this.networkPolicyReady === initialization) {
      576→          this.networkPolicyReady = undefined;
      577→          this.networkPolicyAbort = undefined;
      578→        }
      579→      });
      580→    }
      581→    await waitForPromise(this.networkPolicyReady, signal);
      582→  }
      583→
      584→  private async initializeGlobalNetworkPolicy(cwd: string, signal: AbortSignal): Promise<void> {
      585→    const current = await this.execute({
      586→      command: 'sbx',
      587→      args: ['policy', 'ls', '--json'],
      588→      cwd,
      589→      stdin: 'ignore',
      590→      signal,
      591→    });
      592→    if (current.exitCode === 0) {
      593→      return;
      594→    }
      595→
      596→    const choice = await this.options.selectNetworkPolicy?.(DOCKER_SANDBOX_NETWORK_POLICY_CHOICES);
      597→    if (!choice) {
      598→      const detail = current.stderr.trim() || current.stdout.trim();
      599→      const suffix = detail ? ` Docker reported: ${detail}` : '';
      600→      throw new Error(`Docker Sandbox global network policy is not initialized.${suffix} Choose Open, Balanced or Locked Down in the interactive CLI, or initialize it with \`sbx policy init\`.`);
      601→    }
      602→
      603→    const preset = networkPolicyPreset(choice);
      604→    await this.requireSuccess({
      605→      command: 'sbx',
      606→      args: ['policy', 'init', preset],
      607→      cwd,
      608→      stdin: 'ignore',
      609→      signal,
      610→    }, `initialize the Docker Sandbox global network policy as ${choice}`);
      611→    this.options.reportNetworkPolicy?.(`Docker Sandbox global network policy initialized as ${choice}. Change it later with \`sbx policy\`.`);
      612→  }
      613→
      614→  private async cleanupSandbox(cwd: string, sandboxName: string): Promise<SandboxCleanupDiagnostic> {
      615→    const cleanup = createExecutionSignal(undefined, this.cleanupTimeoutMs);
      616→    try {
      617→      const result = await this.execute({
      618→        command: 'sbx',
      619→        args: ['rm', '--force', sandboxName],
      620→        cwd,
      621→        stdin: 'ignore',
      622→        signal: cleanup.signal,
      623→      });
      624→      if (cleanup.timedOut()) {
      625→        return {
      626→          attempted: true,
      627→          timedOut: true,
      628→          exitCode: result.exitCode,
      629→          stdout: result.stdout,
      630→          stderr: result.stderr,
      631→          error: cleanupTimeoutMessage(this.cleanupTimeoutMs),
      632→        };
      633→      }
      634→      return {
      635→        attempted: true,
      636→        exitCode: result.exitCode,
      637→        stdout: result.stdout,
      638→        stderr: result.stderr,
      639→      };
      640→    } catch (error: unknown) {
      641→      return cleanup.timedOut()
      642→        ? { attempted: true, timedOut: true, error: cleanupTimeoutMessage(this.cleanupTimeoutMs) }
      643→        : { attempted: true, error: formatUnknownError(error) };
      644→    } finally {
      645→      cleanup.dispose();
      646→    }
      647→  }
      648→
      649→  private async requireCapability(cwd: string, args: string[], capability: string, signal?: AbortSignal, matchOutput = true): Promise<void> {
      650→    const result = await this.requireSuccess({ command: 'sbx', args, cwd, stdin: 'ignore', signal }, `verify Docker Sandbox capability ${capability}`);
      651→    if (matchOutput && !`${result.stdout}\n${result.stderr}`.includes(capability)) {
      652→      throw new Error(`Installed sbx does not provide the required ${capability} capability. Upgrade Docker Sandboxes (sbx) and retry.`);
      653→    }
      654→  }
      655→
      656→  private async requireSuccess(request: SubprocessRequest, action: string): Promise<SubprocessResult> {
      657→    const result = await this.execute(request);
      658→    this.assertSuccess(result, action);
      659→    return result;
      660→  }
      661→
      662→  private assertSuccess(result: SubprocessResult, action: string): void {
      663→    if (result.exitCode !== 0) {
      664→      const detail = result.stderr.trim() || result.stdout.trim() || `exit code ${result.exitCode}`;
      665→      throw new Error(`Unable to ${action}: ${detail}`);
      666→    }
      667→  }
      668→
      669→  private async readSandboxId(cwd: string, sandboxName: string, signal?: AbortSignal): Promise<string | undefined> {
      670→    const listed = await this.execute({ command: 'sbx', args: ['ls', '--json'], cwd, stdin: 'ignore', signal });
      671→    if (listed.exitCode !== 0 || !listed.stdout.trim()) return undefined;
      672→    try {
      673→      return parseSandboxList(listed.stdout).find(resource => resource.name === sandboxName)?.id;
      674→    } catch {
      675→      // Older or vendor-patched sbx builds may expose a non-standard payload.
      676→      // The deterministic name remains the minimum identity until reconciliation.
      677→      return undefined;
      678→    }
      679→  }
